        color,n=Counter(grid[r][c] for r in range(h)).most_common(1)[0]
        if color!=bg and n>=h-2: vc.append((c,color))
    # The reduced picture consists of one row/column for every separator,
    # while intermediate stripes are represented by their dominant color.
    rows=[]
    rstarts=[0]+[r+1 for r,_ in hr]
    rend=[r for r,_ in hr]+[h]
    for a,b in zip(rstarts,rend):
        if a<b:
            rows.append(('region',a,b))
        if b<h: rows.append(('line',b,b+1))
    cols=[]; a=0
    for c,color in vc:
        if a<c: cols.append(('region',a,c,None))
        cols.append(('line',c,c+1,color)); a=c+1
    if a<w: cols.append(('region',a,w,None))
    out=[]
    for typ,ra,rb in rows:
        row=[]
        for ct,ca,cb,color in cols:
