    from collections import Counter
    h,w=len(grid),len(grid[0])
    # Pick each stripe's characteristic value, then reduce repeated identical
    # adjacent rows/columns while keeping the crossings and line colors.
    rowvals=[]
    for row in grid:
        rowvals.append(Counter(row).most_common(1)[0][0])
    colvals=[]
    for c in range(w):
        colvals.append(Counter(grid[r][c] for r in range(h)).most_common(1)[0][0])
    # Keep rows where the dominant color changes, and columns with a stable
    # distinctive vertical stripe; sample the original pattern at those indices.
    rr=[]
    for r in range(h):
        if r==0 or rowvals[r]!=rowvals[r-1]: rr.append(r)
    cc=[]
    for c in range(w):
        if c==0 or colvals[c]!=colvals[c-1]: cc.append(c)
    return [[grid[r][c] for c in cc] for r in rr]
